function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100) return 'nums needs 1 to 100 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 10000)) return 'Each value is a whole number from 1 to 10^4.';
  if (!Number.isInteger(k) || k < 1 || k > nums.length) return 'k is between 1 and nums.length.';
  return null;
}

