function largestSumOfAverages(nums, k) {
  const n = nums.length;
  const prefix = new Array(n + 1).fill(0);
  for (let i = 0; i < n; i++) {
    prefix[i + 1] = prefix[i] + nums[i];
  }

  // dp[groups][start]: best score for nums[start..] cut into at most `groups` pieces.
  const dp = Array.from({ length: k + 1 }, () => new Array(n).fill(0));
  for (let start = 0; start < n; start++) {
    dp[1][start] = (prefix[n] - prefix[start]) / (n - start);
  }

  for (let groups = 2; groups <= k; groups++) {
    for (let start = 0; start < n; start++) {
      let best = dp[groups - 1][start];
      for (let end = start + 1; end < n; end++) {
        const average = (prefix[end] - prefix[start]) / (end - start);
        best = Math.max(best, average + dp[groups - 1][end]);
      }
      dp[groups][start] = best;
    }
  }
  return dp[k][0];
}

