function largestSumOfAverages(nums, k) {
  // Try every way to cut the array into at most k pieces, left to right.
  let best = -Infinity;
  const explore = (start, piecesLeft, score) => {
    if (start === nums.length) { best = Math.max(best, score); return; }
    if (piecesLeft === 0) return;
    let sum = 0;
    for (let end = start; end < nums.length; end++) {
      sum += nums[end];
      explore(end + 1, piecesLeft - 1, score + sum / (end - start + 1));
    }
  };
  explore(0, k, 0);
  return best;
}

