function generate(rand, size) {
  const n = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 10);
  const top = size === 'large' || rand() < 0.3 ? 10000 : (rand() < 0.5 ? 3 : 20);
  const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  const k = 1 + Math.floor(rand() * n);
  return [nums, k];
}
